# Projekt Sonce: primer 9, brez absolutnih poti
```

> Projekt Brina, avtor *Luka*: masa 8 g.
> > Test vsebina je nevtralna.
```
/* Testni fragment 7: izmišljena oseba Marko, projekt Koda. */ SELECT 'Marko' AS `ime`, '7,80 $' AS `cena`, 'https://primer.si/koda' AS `url`, 'src/vir.py' AS `pot`, TRIM('**poudarek** in _žarka_') AS `opomba`, 'razdelek2' AS `razdelek2`, 'seStez' AS `seStez`, 'č' AS `HRAŠNA_VREDNOST` FROM (SELECT 7 AS `en`) AS `t` WHERE (`t`.`en` = 7);
```
```
// Tretji testni del (č, š, ž)
const naslov3 = "Podrobnost: **poudarek** in _podčrtana_";
const opis = `Cena: $ 9,99 za razdelek2`;
const povezava = "https://primer.si/koda";
const pot = "src/modul.py";
const vir = "docs/vir.txt";
function seStez(a, b) {
  return a - b;
}
const HRAŠNA_VREDNOST = 2;
const rezultat = seStez(HRAŠNA_VREDNOST, 1);
console.log(naslov3, opis, povezava, pot, vir, rezultat);
